mapper.select:
SELECT cr.user_id, cr.user_name, MAX(d.dept_name) AS dept_name, COUNT(DISTINCT cr.clock_date) AS work_days, COUNT(CASE WHEN cr.status IN ('late','abnormal') THEN 1 END) AS late_count, COUNT(CASE WHEN cr.status IN ('early','abnormal') THEN 1 END) AS early_count, COUNT(CASE WHEN (cr.clock_in_time IS NULL) XOR (cr.clock_out_time IS NULL) THEN 1 END) AS absent_count FROM att_clock_record cr LEFT JOIN sys_user_dept ud ON cr.user_id = ud.user_id LEFT JOIN sys_dept d ON ud.dept_id = d.id
cr.del_flag = 0 AND cr.clock_date BETWEEN #{monthStart} AND #{monthEnd}
AND cr.user_name LIKE CONCAT('%', #{userName}, '%')
AND ud.dept_id = #{deptId}
GROUP BY cr.user_id, cr.user_name ORDER BY work_days DESC, cr.user_id
